import{_ as l,a0 as r,w as a,s as p,I as m,x as t,a1 as o,A as i,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"使用 smem 可視化顯示Linux內存使用情況 | LCTT x X-CMD","titleTemplate":false,"description":"使用 smem 可視化顯示Linux內存使用情況 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 smem 可視化顯示Linux內存使用情況 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 smem 可視化顯示Linux內存使用情況 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141120 How to visualize memory usage on Linux","title":"使用 smem 可視化顯示Linux內存使用情況","tag":"201412","desc":""},"relativePath":"201412/20141120 How to visualize memory usage on Linux.md","filePath":"[post].md"}'),u={name:"201412/20141120 How to visualize memory usage on Linux.md"};function d(S,e,f,x,g,L){const s=r("Link");return a(),p("div",null,[e[21]||(e[21]=m("h1",{id:"使用-smem-可視化顯示linux內存使用情況",tabindex:"-1"},[t("使用 smem 可視化顯示Linux內存使用情況 "),m("a",{class:"header-anchor",href:"#使用-smem-可視化顯示linux內存使用情況","aria-label":"Permalink to “使用 smem 可視化顯示Linux內存使用情況”"},"​")],-1)),e[22]||(e[22]=m("p",null,"物理內存不足對Linux桌面系統和服務器系統的性能影響都很大。當你的計算機變慢時，要做的第一件事就是釋放內存。尤其是在多用户環境以及執行關鍵任務的服務器環境下，內存消耗會變得更加關鍵，因為多個用户和應用線程會同時競爭更多的內存空間。",-1)),m("p",null,[e[1]||(e[1]=t("如果要監測系統內各種資源的使用情況（比如説CPU或內存），圖形化顯示是一種高效的方法，通過圖形界面可以快速分析各用户和進程的資源消耗情況。本教程將給大家介紹",-1)),e[2]||(e[2]=m("strong",null,"在linux下圖形化分析內存使用情況",-1)),e[3]||(e[3]=t("的方法，使用到命令列工具是",-1)),o(s,{href:"http://www.selenic.com/smem/"},{default:i(()=>[...e[0]||(e[0]=[t("smem",-1)])]),_:1}),e[4]||(e[4]=t(".",-1))]),e[23]||(e[23]=n(`<h3 id="物理內存使用情況-rss-、-pss-和-uss" tabindex="-1">物理內存使用情況: RSS 、 PSS 和 USS <a class="header-anchor" href="#物理內存使用情況-rss-、-pss-和-uss" aria-label="Permalink to “物理內存使用情況: RSS 、 PSS 和 USS”">​</a></h3><p>由於Linux使用到了虛擬內存（virtual memory），因此要準確的計算一個進程實際使用的物理內存就不是那麼簡單。 只知道進程的虛擬內存大小也並沒有太大的用處，因為還是無法獲取到實際分配的物理內存大小。</p><ul><li><strong>RSS（Resident set size）</strong>，使用top命令可以查詢到，是最常用的內存指標，表示進程佔用的物理內存大小。但是，將各進程的RSS值相加，通常會超出整個系統的內存消耗，這是因為RSS中包含了各進程間共享的內存。</li><li><strong>PSS（Proportional set size）</strong>會更準確一些，它將共享內存的大小進行平均後，再分攤到各進程上去。</li><li><strong>USS(Unique set size )</strong>是PSS中自己的部分，它只計算了進程獨自佔用的內存大小，不包含任何共享的部分。</li></ul><h3 id="安裝smem" tabindex="-1">安裝Smem <a class="header-anchor" href="#安裝smem" aria-label="Permalink to “安裝Smem”">​</a></h3><p>smem是一個能夠生成多種內存耗用報告的命令列工具，它從/proc文件系統中提取各進程的PSS/USS信息，並進行彙總輸出。它還內建了圖表的生成能力，所以能夠方便地分析整個系統的內存使用情況。</p><h4 id="在debian-ubuntu-或-linux-mint-上安裝smem" tabindex="-1">在Debian, Ubuntu 或 Linux Mint 上安裝smem <a class="header-anchor" href="#在debian-ubuntu-或-linux-mint-上安裝smem" aria-label="Permalink to “在Debian, Ubuntu 或 Linux Mint 上安裝smem”">​</a></h4><pre><code>$ sudo apt-get install smem 
</code></pre><h4 id="在fedora-或-centos-rhel上安裝smem" tabindex="-1">在Fedora 或 CentOS/RHEL上安裝Smem <a class="header-anchor" href="#在fedora-或-centos-rhel上安裝smem" aria-label="Permalink to “在Fedora 或 CentOS/RHEL上安裝Smem”">​</a></h4>`,8)),m("p",null,[e[6]||(e[6]=t("在CentOS/RHEL上，你首先得",-1)),o(s,{href:"http://xmodulo.com/how-to-set-up-epel-repository-on-centos.html"},{default:i(()=>[...e[5]||(e[5]=[t("啓用",-1)])]),_:1}),e[7]||(e[7]=t("EPEL倉庫。",-1))]),e[24]||(e[24]=n(`<pre><code>$ sudo yum install smem python-matplotlib 
</code></pre><h3 id="使用smem檢查內存使用情況" tabindex="-1">使用smem檢查內存使用情況 <a class="header-anchor" href="#使用smem檢查內存使用情況" aria-label="Permalink to “使用smem檢查內存使用情況”">​</a></h3><p>你可以在非特權模式下使用smem，它能夠顯示當前用户運行的所有進程的內存使用情況，並按照PSS的大小進行排序。</p><pre><code>$ smem 
</code></pre><p><img src="https://farm8.staticflickr.com/7498/15801819892_d017280595_z.jpg" alt=""></p><p>如有你想得到整個系統中所有用户的內存使用情況，就需要使用root權限來運行smem。</p><pre><code>$ sudo smem 
</code></pre><p><img src="https://farm9.staticflickr.com/8635/15776587626_1de74c4bcd_z.jpg" alt=""></p><p>也可以按用户維度來輸出報告：</p><pre><code>$ sudo smem -u 
</code></pre><p><img src="https://farm9.staticflickr.com/8543/15798375491_510698d98f_z.jpg" alt=""></p><p>smem提供了以下選項來對輸出結果進行篩選，支持按映射方式（mapping）、進程和用户三個維度的篩選：</p><ul><li>-M &lt;正則表達式&gt;</li><li>-P &lt;正則表達式&gt;</li><li>-U &lt;正則表達式&gt;</li></ul><p>想了解smem更多的使用方式，可以查詢用户手冊（man page）。</p><h3 id="使用smem圖形化顯示內存使用情況" tabindex="-1">使用smem圖形化顯示內存使用情況 <a class="header-anchor" href="#使用smem圖形化顯示內存使用情況" aria-label="Permalink to “使用smem圖形化顯示內存使用情況”">​</a></h3><p>圖形化的報告使用起來會更加方便快捷。smem支持兩種格式的圖形顯示方式：直方圖和餅圖。</p><p>下面是一些圖形化顯示的實例。</p><p>下面的命令列會基於PSS/RSS值，生成直方圖，以用户alice為例。</p><pre><code>$ sudo smem --bar name -c &quot;pss uss&quot; -U alice 
</code></pre><p><img src="https://farm6.staticflickr.com/5616/15614838448_640e850cd8_z.jpg" alt=""></p><p>這個例子會生成一張餅圖，圖中顯示了系統中各進程的PSS內存使用量：</p><pre><code>$ sudo smem --pie name -c &quot;pss&quot; 
</code></pre><p><img src="https://farm8.staticflickr.com/7466/15614838428_eed7426cfe_z.jpg" alt=""></p><p>概括來説，smem是一個方便易用的內存分析工具。利用smem的格式化輸出，你可以對內存使用報告進行自動化分析，並執行一些自動化的處理措施。如果你還知道其他的一些優秀的內存檢測工具，請在留言區告訴我。</p><hr>`,25)),m("p",null,[e[9]||(e[9]=t("via: ",-1)),o(s,{href:"http://xmodulo.com/visualize-memory-usage-linux.html"},{default:i(()=>[...e[8]||(e[8]=[t("http://xmodulo.com/visualize-memory-usage-linux.html",-1)])]),_:1})]),m("p",null,[e[13]||(e[13]=t("作者：",-1)),o(s,{href:"http://xmodulo.com/author/nanni"},{default:i(()=>[...e[10]||(e[10]=[t("Dan Nanni",-1)])]),_:1}),e[14]||(e[14]=t(" 譯者：",-1)),o(s,{href:"https://github.com/coloka"},{default:i(()=>[...e[11]||(e[11]=[t("coloka",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:i(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),m("p",null,[e[18]||(e[18]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創翻譯，",-1)),o(s,{href:"http://linux.cn/"},{default:i(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const h=l(u,[["render",d]]);export{P as __pageData,h as default};
